return {
  attack: {
    hook: "onEvent",
    event: { type: "reload", phase: "before" },
    promptOnPlayer: async (H, actor, ctx) => {
      if (ctx.payload.weaponType !== "Shotgun" || !H.zone.isClose(H.zone.of(actor))) return false;
      if (!(await H.ask.confirm({
        title: "Kicking and Screaming",
        bodyHtml: "Make an immediate <strong>1/1 Hard</strong> attack before reloading?",
      }))) return false;
      await H.actions.attack(actor, {
        title: "Kicking and Screaming",
        weaponless: true,
        forcedProfile: { stat: "hard", defence: "close" },
        damageOverride: { resolve: 1, wounds: 1 },
      });
      return true;
    },
  },
};
